      <section class="chart-wrap" aria-label="Matrix chart of internet penetration inequality by region and dimension">
        <svg id="chart" viewBox="0 0 1484 780" role="img" aria-label="Internet penetration rates by income quintile, age group, urban rural setting, and region in percent">
          <rect x="0" y="0" width="1484" height="780" fill="#fffdf8"/>
          <text x="13" y="30" class="title-label">Region / overall</text>
          <text x="295" y="30" class="title-label">Income gradient</text>
          <text x="705" y="30" class="title-label">Age gradient</text>
          <text x="1115" y="30" class="title-label">Urban–rural split</text>
          <text x="13" y="55" class="small muted">Overall penetration; population encoded in label</text>
          <text x="295" y="55" class="small muted">Q1 lowest income → Q5 highest income</text>
          <text x="705" y="55" class="small muted">65+ → 15–24, all age bands shown</text>
          <text x="1115" y="55" class="small muted">Rural → urban</text>
