        <span>Source data: synthesized 2023 estimates from ITU, World Bank and Pew Research Center methodologies.</span>
      </section>
    </section>
  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    var currentTheme = 'light';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      currentTheme = t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    function downloadImage() {
      var node = document.getElementById('viz-root');
      htmlToImage.toPng(node, { pixelRatio: 2, backgroundColor: '#f7f3ea' }).then(function(dataUrl) {
        var link = document.createElement('a');
        link.download = 'digital-divide-chart.png';
        link.href = dataUrl;
        link.click();
      });
    }
    function onThemeChange() {}
    function checkChartJs() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
    }
    checkChartJs();

    var regions = ['Sub-Saharan Africa', 'South Asia', 'Europe', 'North America'];
    var population = {
      'Sub-Saharan Africa': { overall: 27, pop: 1210, users: 327 },
      'South Asia': { overall: 40, pop: 1980, users: 792 },
      'Europe': { overall: 89, pop: 750, users: 668 },
      'North America': { overall: 93, pop: 380, users: 353 }
    };
    var income = {
      'Sub-Saharan Africa': [6,14,25,42,68],
      'South Asia': [12,24,39,56,78],
      'Europe': [72,82,89,94,97],
      'North America': [75,85,92,96,99]
    };
    var ages = {
      'Sub-Saharan Africa': [5,11,18,26,32,38],
      'South Asia': [8,16,27,38,48,55],
      'Europe': [58,79,88,93,96,98],
      'North America': [65,84,91,95,97,99]
    };
    var urban = {
      'Sub-Saharan Africa': { rural: 13, urban: 42 },
      'South Asia': { rural: 22, urban: 58 },
      'Europe': { rural: 78, urban: 92 },
      'North America': { rural: 80, urban: 95 }
    };
    var svg = document.getElementById('chart');
    var rowsG = document.getElementById('rows');
    var gridG = document.getElementById('grid');
    var legendG = document.getElementById('legend');
    var panels = [
      { x: 295, w: 320 },
      { x: 705, w: 320 },
      { x: 1115, w: 320 }
    ];
    function el(name, attrs, parent) {
      var node = document.createElementNS('http://www.w3.org/2000/svg', name);
      for (var key in attrs) node.setAttribute(key, attrs[key]);
      (parent || svg).appendChild(node);
      return node;
    }
    function text(value, x, y, cls, parent) {
      var t = el('text', { x: x, y: y, class: cls }, parent);
      t.textContent = value;
      return t;
    }
    function sx(panel, value) { return panel.x + (value / 100) * panel.w; }
    function drawAxis(panel, yTop, yBottom) {
      var ticks = [0,25,50,75,100];
      for (var i = 0; i < ticks.length; i++) {
        var x = sx(panel, ticks[i]);
        el('line', { x1: x, x2: x, y1: yTop, y2: yBottom, class: ticks[i] === 50 ? 'grid-major' : 'grid' }, gridG);
        text(ticks[i] + '%', x - 12, 78, 'tiny muted', gridG);
      }
      el('line', { x1: panel.x, x2: panel.x + panel.w, y1: 83, y2: 83, class: 'axis' }, gridG);
      el('text', { x: panel.x + panel.w + 8, y: 78, class: 'tiny muted' }, gridG).textContent = 'penetration';
    }
    for (var p = 0; p < panels.length; p++) drawAxis(panels[p], 88, 668);

    function dot(parent, cx, cy, r, fill, stroke) {
      el('circle', { cx: cx, cy: cy, r: r, fill: fill, stroke: stroke || '#fffdf8', 'stroke-width': 2.5 }, parent);
    }
    function drawSeries(parent, panel, y, values, gapLabel, hot) {
      var start = sx(panel, values[0]);
      var end = sx(panel, values[values.length - 1]);
      el('line', { x1: start, x2: end, y1: y, y2: y, class: hot ? 'low-line' : 'mid-line' }, parent);
      for (var i = 0; i < values.length; i++) {
        var fill = '#8a8377';
        var radius = 6;
        if (i === 0) { fill = '#b43b2f'; radius = 8; }
        if (i === values.length - 1) { fill = '#1d4e89'; radius = 8; }
        dot(parent, sx(panel, values[i]), y, radius, fill);
      }
      text(values[0] + '%', start - 13, y - 14, 'tiny label', parent);
      text(values[values.length - 1] + '%', end - 13, y - 14, 'tiny label', parent);
      text(gapLabel, panel.x + panel.w + 16, y + 5, hot ? 'gap gap-hot' : 'gap', parent);
    }
    function drawUrban(parent, panel, y, rural, urbanValue, gapLabel, hot) {
      el('line', { x1: sx(panel, rural), x2: sx(panel, urbanValue), y1: y, y2: y, class: hot ? 'low-line' : 'mid-line' }, parent);
      dot(parent, sx(panel, rural), y, 8, '#b43b2f');
      dot(parent, sx(panel, urbanValue), y, 8, '#1d4e89');
      text('R ' + rural + '%', sx(panel, rural) - 19, y - 14, 'tiny label', parent);
      text('U ' + urbanValue + '%', sx(panel, urbanValue) - 19, y - 14, 'tiny label', parent);
      text(gapLabel, panel.x + panel.w + 16, y + 5, hot ? 'gap gap-hot' : 'gap', parent);
    }
    var rowTop = 103;
    var rowH = 139;
    for (var r = 0; r < regions.length; r++) {
      var region = regions[r];
      var y0 = rowTop + r * rowH;
      var cy = y0 + 70;
      var g = el('g', {}, rowsG);
      el('rect', { x: 0, y: y0, width: 1484, height: rowH, fill: r % 2 === 0 ? '#fffdf8' : '#f8f4eb' }, g);
      el('line', { x1: 0, x2: 1484, y1: y0, y2: y0, stroke: '#ded5c5', 'stroke-width': 1 }, g);
      text(region, 13, y0 + 38, 'big label', g);
      var info = population[region];
      text(info.pop.toLocaleString() + 'M people · ' + info.users + 'M users', 13, y0 + 62, 'small muted', g);
      el('rect', { x: 15, y: y0 + 82, width: 205, height: 16, rx: 8, class: 'overall-bg' }, g);
      el('rect', { x: 15, y: y0 + 82, width: (info.overall / 100) * 205, height: 16, rx: 8, class: 'overall-bar' }, g);
      text(info.overall + '% overall', 230, y0 + 96, 'medium label', g);
      var inc = income[region];
      var incGap = inc[4] - inc[0];
      drawSeries(g, panels[0], cy, inc, incGap + ' pp', incGap >= 60);
      var age = ages[region];
      var ageGap = age[5] - age[0];
      drawSeries(g, panels[1], cy, age, ageGap + ' pp', ageGap >= 45);
      var st = urban[region];
      var urGap = st.urban - st.rural;
      drawUrban(g, panels[2], cy, st.rural, st.urban, urGap + ' pp', urGap >= 35);
    }
    var call = el('g', {}, rowsG);
    el('rect', { x: 1066, y: 257, width: 196, height: 47, rx: 6, class: 'callout' }, call);
    text('Largest settlement gap:', 1080, 277, 'callout-text', call);
    text('South Asia, 36 pp', 1080, 296, 'callout-text', call);
    el('rect', { x: 242, y: 257, width: 200, height: 47, rx: 6, class: 'callout' }, call);
    text('Steepest income gap:', 256, 277, 'callout-text', call);
    text('South Asia, 66 pp', 256, 296, 'callout-text', call);
    el('rect', { x: 654, y: 257, width: 192, height: 47, rx: 6, class: 'callout' }, call);
    text('Widest age gap:', 668, 277, 'callout-text', call);
    text('South Asia, 47 pp', 668, 296, 'callout-text', call);

    var ly = 714;
    text('Legend', 13, ly, 'title-label', legendG);
    el('line', { x1: 98, x2: 188, y1: ly - 5, y2: ly - 5, class: 'legend-line' }, legendG);
    dot(legendG, 98, ly - 5, 8, '#b43b2f');
    dot(legendG, 188, ly - 5, 8, '#1d4e89');
    text('Span from lower-access group to higher-access group', 205, ly, 'small muted', legendG);
    dot(legendG, 555, ly - 5, 6, '#8a8377');
    text('Intermediate quintiles or age bands', 570, ly, 'small muted', legendG);
    el('rect', { x: 806, y: ly - 16, width: 70, height: 14, rx: 7, class: 'overall-bg' }, legendG);
    el('rect', { x: 806, y: ly - 16, width: 42, height: 14, rx: 7, class: 'overall-bar' }, legendG);
    text('Overall regional penetration', 890, ly, 'small muted', legendG);
    text('Endpoint definitions: income Q1→Q5; age 65+→15–24; settlement Rural→Urban.', 13, 748, 'small muted', legendG);
