      --negative: #b43b2f;
      --warning: #c78a1f;
    }
    .theme-dark {
      --bg: #11100e;
      --surface: #1c1a17;
      --surface-hover: #27231e;
      --border: #4b4438;
      --text: #f7f3ea;
      --text-secondary: #c7bda9;
      --accent: #df6659;
      --accent-secondary: #7aa2d6;
      --positive: #78b8a9;
      --negative: #df6659;
      --warning: #e7b24f;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }
    .skip-link, .skip-to-content { position: absolute; left: -9999px; }
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 50; display: none; }
    .viz-menu-toggle { border: 1px solid var(--border); background: var(--surface); color: var(--text); border-radius: 10px; padding: 8px; }
    .viz-menu-dropdown { display: none; position: absolute; right: 0; top: 42px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 8px; box-shadow: 0 12px 30px rgba(0,0,0,.16); }
    .viz-menu-dropdown.open { display: grid; gap: 6px; }
    .viz-menu-dropdown button { background: transparent; border: 0; color: var(--text); padding: 8px 10px; text-align: left; white-space: nowrap; }
    main { width: 1600px; height: 1000px; margin: 0 auto; background: var(--bg); }
    .frame { width: 1600px; height: 1000px; padding: 46px 58px 38px; position: relative; }
    header { display: grid; grid-template-columns: 1fr 390px; gap: 30px; align-items: start; border-bottom: 2px solid #211f1a; padding-bottom: 18px; }
    .kicker { font-size: 14px; letter-spacing: .16em; text-transform: uppercase; color: var(--negative); font-weight: 850; margin-bottom: 9px; }
    h1 { margin: 0; font-size: 49px; line-height: .98; letter-spacing: -0.045em; max-width: 1020px; }
    .subtitle { margin: 12px 0 0; max-width: 1030px; color: var(--text-secondary); font-size: 20px; line-height: 1.32; }
    .note { border-left: 5px solid var(--negative); padding: 7px 0 7px 16px; font-size: 18px; line-height: 1.32; color: var(--text); background: rgba(180,59,47,.06); }
    .note strong { font-size: 34px; line-height: 1; display: block; letter-spacing: -.04em; color: var(--negative); }
    .chart-wrap { margin-top: 22px; background: var(--surface); border: 1px solid var(--border); box-shadow: 0 14px 45px rgba(33,31,26,.08); padding: 20px 22px 14px; }
    svg { display: block; width: 100%; height: auto; }
    .axis { stroke: #211f1a; stroke-width: 1.25; }
    .grid { stroke: #d7cdbc; stroke-width: 1; }
    .grid-major { stroke: #bfb3a0; stroke-width: 1.2; }
    .panel-border { stroke: #d9d0bf; stroke-width: 1; fill: none; }
    .row-band:nth-child(even) { fill: #f8f4eb; }
    .label { fill: var(--text); font-weight: 750; }
    .muted { fill: var(--text-secondary); }
    .tiny { font-size: 12px; }
    .small { font-size: 14px; }
    .medium { font-size: 16px; }
    .big { font-size: 22px; font-weight: 850; }
    .title-label { font-size: 18px; font-weight: 900; letter-spacing: -.01em; }
    .gap { font-size: 15px; font-weight: 900; fill: #211f1a; }
    .gap-hot { fill: var(--negative); }
    .low-line { stroke: #ba4438; stroke-width: 5; stroke-linecap: round; opacity: .95; }
    .mid-line { stroke: #8a8377; stroke-width: 3; stroke-linecap: round; opacity: .58; }
    .overall-bar { fill: #1f1f1d; opacity: .86; }
    .overall-bg { fill: #e7decf; }
    .callout { fill: #fff8ea; stroke: #b43b2f; stroke-width: 1.4; }
    .callout-text { fill: #7d2119; font-weight: 850; font-size: 15px; }
    .legend-line { stroke: #211f1a; stroke-width: 3; stroke-linecap: round; }
    .legend-dot-low { fill: #b43b2f; stroke: #fffdf8; stroke-width: 2; }
    .legend-dot-high { fill: #1d4e89; stroke: #fffdf8; stroke-width: 2; }
    .legend-dot-mid { fill: #8a8377; stroke: #fffdf8; stroke-width: 1.5; }
    .source { display: flex; justify-content: space-between; gap: 20px; color: var(--text-secondary); font-size: 12px; margin-top: 10px; border-top: 1px solid var(--border); padding-top: 9px; }
    .card:hover { transform: translateY(-1px); }
    @keyframes fadeUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    .animate { animation: fadeUp .5s ease both; }
    .reveal { opacity: 1; }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }
    @media print { .viz-menu { display: none; } body { background: white; } main { width: 100%; height: auto; } }
